/*
 * Klee - Userspace bwrap translation layer
 * i386 (compat) syscall numbers
 *
 * A 32-bit tracee uses the i386 syscall table: different numbers, six
 * arguments in ebx/ecx/edx/esi/edi/ebp, and a handful of spellings that
 * x86_64 does not have (stat64, getuid32, fcntl64, socketcall, ipc ...).
 * klee's handlers are registered under x86_64 numbers, so every i386
 * syscall is mapped onto the x86_64 number with the same meaning before
 * dispatch.  The table is generated by scripts/gen_sysnum32.py.
 */
#ifndef KLEE_SYSNUM32_H
#define KLEE_SYSNUM32_H

#include <stddef.h>
#include <stdint.h>

/* The user-visible struct has a legacy layout (old stat, oldolduname):
 * exit handlers must not rewrite it. */
#define KLEE_SYS32_OLDSTRUCT 0x1
/* socketcall / ipc: split into the real call at syscall entry. */
#define KLEE_SYS32_DEMUX     0x2

typedef struct {
    uint16_t nr32;
    int16_t nr64;      /* -1: no x86_64 counterpart */
    uint8_t flags;
} KleeSysnum32Entry;

extern const KleeSysnum32Entry klee_sysnum32_table[];
extern const size_t klee_sysnum32_table_len;

#define KLEE_SYS32_socketcall 102
#define KLEE_SYS32_ipc        117

/* x86_64 number for an i386 syscall, or -1 if there is none.  flags_out
 * (may be NULL) receives the KLEE_SYS32_* flags of the entry. */
int klee_sysnum_i386_to_x64(int nr32, unsigned *flags_out);

/* All i386 numbers that map onto nr64 (stat64, oldstat and stat all map
 * onto stat).  Returns how many were stored in out. */
size_t klee_sysnum_x64_to_i386(int nr64, int *out, size_t max);

#endif /* KLEE_SYSNUM32_H */
